// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// PostAccount Create an account for a device code, or return the existing one
	// (POST /accounts)
	PostAccount(ctx context.Context, request PostAccountRequestObject) (PostAccountResponseObject, error)
	// GetAccount Read an account
	// (GET /accounts/{code})
	GetAccount(ctx context.Context, request GetAccountRequestObject) (GetAccountResponseObject, error)
	// PutAccount Set or reset the account's own server
	// (PUT /accounts/{code})
	PutAccount(ctx context.Context, request PutAccountRequestObject) (PutAccountResponseObject, error)
	// GetHealth Liveness and database check
	// (GET /healthz)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// PostMessage Upload a recording
	// (POST /messages)
	PostMessage(ctx context.Context, request PostMessageRequestObject) (PostMessageResponseObject, error)
	// Login Sign in with email and password
	// (POST /v1/auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout End the current session
	// (POST /v1/auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// Register Create an account with an invitation code, and sign in
	// (POST /v1/auth/register)
	Register(ctx context.Context, request RegisterRequestObject) (RegisterResponseObject, error)
	// ApproveDevicePairing Pair the watch that shows this code with the signed-in user
	// (POST /v1/device/approve)
	ApproveDevicePairing(ctx context.Context, request ApproveDevicePairingRequestObject) (ApproveDevicePairingResponseObject, error)
	// StartDevicePairing A watch asks to be paired
	// (POST /v1/device/code)
	StartDevicePairing(ctx context.Context, request StartDevicePairingRequestObject) (StartDevicePairingResponseObject, error)
	// GetDevicePairing What a user code is waiting for
	// (GET /v1/device/pairing/{userCode})
	GetDevicePairing(ctx context.Context, request GetDevicePairingRequestObject) (GetDevicePairingResponseObject, error)
	// PollDevicePairing The watch asks whether its pairing was approved
	// (POST /v1/device/token)
	PollDevicePairing(ctx context.Context, request PollDevicePairingRequestObject) (PollDevicePairingResponseObject, error)
	// ListDevices The user's paired watches
	// (GET /v1/devices)
	ListDevices(ctx context.Context, request ListDevicesRequestObject) (ListDevicesResponseObject, error)
	// RevokeDevice Revoke a watch
	// (DELETE /v1/devices/{id})
	RevokeDevice(ctx context.Context, request RevokeDeviceRequestObject) (RevokeDeviceResponseObject, error)
	// GetMe The signed-in user
	// (GET /v1/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// ChangePassword Change the password
	// (POST /v1/me/password)
	ChangePassword(ctx context.Context, request ChangePasswordRequestObject) (ChangePasswordResponseObject, error)
	// ListMessages The user's recordings, newest first
	// (GET /v1/messages)
	ListMessages(ctx context.Context, request ListMessagesRequestObject) (ListMessagesResponseObject, error)
	// UploadMessage A watch uploads a recording
	// (POST /v1/messages)
	UploadMessage(ctx context.Context, request UploadMessageRequestObject) (UploadMessageResponseObject, error)
	// DeleteMessage Delete a recording and its files
	// (DELETE /v1/messages/{id})
	DeleteMessage(ctx context.Context, request DeleteMessageRequestObject) (DeleteMessageResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// PostAccount operation middleware
func (sh *strictHandler) PostAccount(w http.ResponseWriter, r *http.Request) {
	var request PostAccountRequestObject

	var body PostAccountJSONRequestBody
	if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
		sh.options.RequestErrorHandlerFunc(w, r, fmt.Errorf("can't decode JSON body: %w", err))
		return
	}
	request.Body = &body

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.PostAccount(ctx, request.(PostAccountRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "PostAccount")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(PostAccountResponseObject); ok {
		if err := validResponse.VisitPostAccountResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

